## Why This Is Asked
Real-world rendering challenges with large lists and bursty updates.

## Key Concepts
- FlatList virtualization
- Memoization and stable keys
- Batched updates and interval flushing
- Native event emitters and bridging

## Code Example
```javascript
import { useEffect, useRef, useState } from 'react';
import { NativeEventEmitter, NativeModules } from 'react-native';

export function useLiveList(channel) {
  const [updates, setUpdates] = useState([]);
  const buf = useRef([]);

  useEffect(() => {
    const emitter = new NativeEventEmitter(NativeModules[channel]);
    const subscription = emitter.addListener('dataUpdate', (data) => {
      buf.current.push(data);
    });

    const flushInterval = setInterval(() => {
      if (buf.current.length > 0) {
        setUpdates(prev => [...prev, ...buf.current]);
        buf.current = [];
      }
    }, 16); // ~60fps

    return () => {
      subscription.remove();
      clearInterval(flushInterval);
    };
  }, [channel]);

  return updates;
}

// Usage in component
function LiveDashboard() {
  const data = useLiveList('LiveDataSource');

  const renderItem = useCallback(({ item }) => (
    <MemoizedListItem item={item} />
  ), []);

  return (
    <FlatList
      data={data}
      renderItem={renderItem}
      getItemLayout={(data, index) => ({ length: 80, offset: 80 * index, index })}
      initialNumToRender={10}
      maxToRenderPerBatch={5}
      windowSize={10}
      removeClippedSubviews
      keyExtractor={(item, index) => `item-${item.id || index}`}
    />
  );
}
```

